IMG_B64 = {'mt_gqa_001176': '', 'mt_gqa_000108': '', 'mt_vqa_v2_000461': '', 'mt_vqa_v2_000023': ''}


_IMG = {}


def disp_of(dlg):
    if dlg not in _IMG:
        _IMG[dlg] = np.array(Image.open(io.BytesIO(base64.b64decode(IMG_B64[dlg])))
                             .convert("RGB"))
    return _IMG[dlg]


def stars(ax, idx, px, s=95, face=CYAN, edge=RED, lw=0.9, hollow=False):
    idx = np.asarray(idx)
    r, c = idx // 24, idx % 24
    kw = dict(marker="*", s=s, linewidth=lw, zorder=5)
    if hollow:
        kw.update(facecolor="none", edgecolor="white")
    else:
        kw.update(facecolor=face, edgecolor=edge)
    ax.scatter((c + 0.5) * px / 24, (r + 0.5) * px / 24, **kw)


def heat_overlay(disp, w, px, mix=0.55):
    wn = (w - w.min()) / (w.max() - w.min() + 1e-9)
    rgb = plt.get_cmap("jet")(wn.reshape(24, 24))[..., :3]
    up = np.array(Image.fromarray((rgb * 255).astype(np.uint8)).resize((px, px),
                                                                      Image.BILINEAR))
    return np.clip(up * mix + disp * mix, 0, 255).astype(np.uint8)


def put_lines(ax, lines, width=46, dy=0.085):
    y = 0.99
    for text, color, size, weight in lines:
        for ln in (textwrap.wrap(text, width) or [""]):
            ax.text(0.02, y, ln, transform=ax.transAxes, va="top", ha="left",
                    fontsize=size, color=color, fontweight=weight, linespacing=1.25)
            y -= dy * (0.82 if size < 8 else 1.0)
        y -= 0.012


def panels(c, outdir):
    dlg = c["dialogue_id"]
    px = c["view_px"]
    disp = disp_of(dlg)
    W = np.array(c["token_weight"])
    fig, axes = plt.subplots(1, 3, figsize=(15.6, 5.4))
    for a in axes:
        a.axis("off"); a.set_box_aspect(1)
    axes[0].imshow(disp)
    axes[1].imshow(disp)
    stars(axes[1], c["fastv_idx"], px)
    stars(axes[1], c["divprune_idx"], px, s=38, face="none", edge="white", lw=0.8)
    axes[2].imshow(heat_overlay(disp, W, px) / 255.0, alpha=0.95)
    stars(axes[2], c["anchor_idx"], px, s=44, hollow=True)
    sm = plt.cm.ScalarMappable(cmap="jet", norm=Normalize(vmin=W.min(), vmax=W.max()))
    cb = fig.colorbar(sm, ax=axes[2], fraction=0.046, pad=0.02)
    cb.set_label("residual merge weight  w", fontsize=10)
    cap = (f"{dlg}  ({c['image_id']})   kept 58/576 (10%)   |   middle: FastV stars + "
           f"DivPrune white outlines   |   right: AnchorMerge weights + anchors")
    fig.suptitle(cap, fontsize=12, y=0.985)
    fig.tight_layout(rect=[0, 0, 1, 0.93])
    out = f"{outdir}/{dlg}_panels.png"
    fig.savefig(out, dpi=150, bbox_inches="tight", facecolor="white"); plt.close(fig)
    print("wrote", out)


def paper(c, outdir):
    dlg = c["dialogue_id"]
    px = c["view_px"]
    disp = disp_of(dlg)
    W = np.array(c["token_weight"])
    ov_f = len(set(c["fastv_idx"]) & set(c["anchor_idx"]))
    ov_d = len(set(c["divprune_idx"]) & set(c["anchor_idx"]))
    FW = 17.2
    w, gap, x0 = 0.2435, 0.0045, 0.008
    col_in = w * FW
    text_in, pad_in = 1.55, 0.30
    FH = col_in + text_in + pad_in
    h_img = col_in / FH
    y_img = 1.0 - pad_in / 2 / FH - h_img
    h_txt, y_txt = text_in / FH, pad_in / 2 / FH
    fig = plt.figure(figsize=(FW, FH))
    panels_img = [disp, disp, disp, heat_overlay(disp, W, px)]
    marks = [None, c["fastv_idx"], c["divprune_idx"], c["anchor_idx"]]
    for i in range(4):
        x = x0 + i * (w + gap)
        ax = fig.add_axes([x, y_img, w, h_img]); ax.axis("off")
        ax.imshow(panels_img[i])
        if marks[i] is not None:
            hollow = i == 3
            stars(ax, marks[i], px, s=70 if not hollow else 44, hollow=hollow)
        tx = fig.add_axes([x, y_txt, w, h_txt]); tx.axis("off")
        if i == 0:
            lines = []
            for t, turn in enumerate(c["turns"], 1):
                lines += [(f"Q{t}: {turn['q']}", BLACK, 8.2, "normal"),
                          (f"      ref: {turn['ref']}", GRAY, 7.0, "normal")]
            put_lines(tx, lines)
        elif i == 3:
            ns = sum(t["am_ok"] for t in c["turns"])
            nf = sum(t["full_ok"] for t in c["turns"])
            lines = [(f"AnchorMerge (ours) @58   {ns}/{len(c['turns'])} correct",
                      BLACK, 9.2, "bold")]
            for t, turn in enumerate(c["turns"], 1):
                lines.append((f"Q{t}: {turn['am']}{' ✓' if turn['am_ok'] else ' ✗'}"
                              f"   [full: {turn['full']}"
                              f"{' ✓' if turn['full_ok'] else ' ✗'}]",
                              GREEN if turn["am_ok"] else RED, 8.0, "normal"))
            lines.append((f"full cache @576: {nf}/{len(c['turns'])} correct", RED, 8.2,
                          "normal"))
            put_lines(tx, lines)
        else:
            name = "FastV" if i == 1 else "DivPrune"
            ov = ov_f if i == 1 else ov_d
            lines = [(f"{name}  @58 (10%)", BLACK, 9.2, "bold"),
                     ("selection only (no answers generated)", GRAY, 8.0, "normal"),
                     (f"overlap with AnchorMerge anchors: {ov}/58", GRAY, 8.0, "normal")]
            put_lines(tx, lines)
    for ext in ("png", "pdf"):
        out = f"{outdir}/{dlg}_paper.{ext}"
        fig.savefig(out, dpi=150, bbox_inches="tight", facecolor="white")
        print("wrote", out)
    plt.close(fig)


def main(outdir):
    os.makedirs(outdir, exist_ok=True)
    for c in DATA["cases"]:
        panels(c, outdir)
        paper(c, outdir)


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "case4mt_figs")
